import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the group to hold the plane and text
  const group = new THREE.Group();
  group.position.set(0, 1.85, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create backdrop plane (~7x6 units at z=-2.5) with gradient
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const gradientCanvas = document.createElement('canvas');
  gradientCanvas.width = 1;
  gradientCanvas.height = 256;
  const ctx2d = gradientCanvas.getContext('2d');

  // Gradient from surface (#0b0b10) to ink (#16161d)
  const grad = ctx2d.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, '#0b0b10');
  grad.addColorStop(1, '#16161d');
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, 1, 256);

  const gradTex = new THREE.CanvasTexture(gradientCanvas);
  gradTex.magFilter = THREE.LinearFilter;
  gradTex.minFilter = THREE.LinearFilter;

  const backdropMat = new THREE.MeshBasicMaterial({ map: gradTex });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Create the hero plane with the provided image
  const planeGeo = new THREE.PlaneGeometry(3.5, 2.2);
  let planeMat;

  // Load the image texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((imgTex) => {
    imgTex.colorSpace = THREE.SRGBColorSpace;
    imgTex.magFilter = THREE.LinearFilter;
    imgTex.minFilter = THREE.LinearFilter;
    planeMat.map = imgTex;
    planeMat.needsUpdate = true;
  });

  planeMat = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 1.0
  });

  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.position.z = 0;
  group.add(plane);

  // Render the hero subhead text
  // "Atelier Noir — precise · luxury · technical"
  const headlineText = ctx.fontAtlas.createText('Atelier Noir — precise · luxury · technical', {
    fontSize: 42,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0
  });

  headlineText.position.set(0, -1.4, 0.1);
  group.add(headlineText);

  // Setup cleanup
  group.userData.cleanup = () => {
    backdropGeo.dispose();
    planeGeo.dispose();
    backdropMat.dispose();
    planeMat.dispose();
    if (planeMat.map) planeMat.map.dispose();
    gradTex.dispose();
    gradientCanvas.remove();
  };

  group.userData.handlers = {};

  return group;
}
